fn smallest_list_length(list: &Vec<Vec<i32>>) -> usize {
    // Initialize min_length to the maximum possible value for usize
    let mut min_length = usize::MAX;

    // Iterate through each inner list
    for inner_list in list {
        // Update min_length if the current inner list is shorter
        let current_length = inner_list.len();
        if current_length < min_length {
            min_length = current_length;
        }
    }

    // Return the minimum length found
    min_length
}